export const PROTOCOL_VERSION = 1;

/** Answer of a <topic>.watch: the subscription and its first data. */
export interface WatchResult<T> {
  sub: string;
  seq: number;
  snapshot: T;
}

/** Every request method: its params and result. */
export interface Methods {
  /** The account's vCPU quota use in the active region. */
  "account.headroom": { params: Empty; result: Quota };
  /** Runs the cloud login that fixes the last expired-login error, narrating its output (browser prompts, device codes) as progress. */
  "auth.login": { params: Empty; result: null };
  /** Answers the agent's permission request: allow or deny. */
  "chat.decide": { params: DecideParams; result: null };
  /** Older items of a session's chat, before the oldest one the client has. */
  "chat.history": { params: HistoryParams; result: HistoryPage };
  /** Stops the agent's turn, as Esc does at its prompt. */
  "chat.interrupt": { params: SessionRef; result: null };
  /** The bottom of the agent's pane as text: what it is doing, without attaching. */
  "chat.peek": { params: PeekParams; result: Peek };
  /** Sends a prompt to a session's agent, once per promptId. A parked session is woken by a background job that delivers it. */
  "chat.send": { params: ChatSendParams; result: ChatSendResult };
  /** A session's agent conversation: the newest items, then changes as the agent writes them. Parked sessions answer from this machine's copy. */
  "chat.watch": { params: SessionRef; result: WatchResult<ChatSnapshot> };
  /** Starts, stops or restarts one of a session's containers. */
  "containers.action": { params: ContainerParams; result: null };
  /** Checks the environment and the cloud account. */
  "doctor.run": { params: Empty; result: Check[] };
  /** What runs in a session — windows, containers, processes, ports, load — pushed every few seconds while watched. */
  "env.watch": { params: SessionRef; result: WatchResult<Env> };
  /** The paths in a session's checkout, tracked and untracked (ignored ones left out). */
  "files.list": { params: FileListParams; result: FileList };
  /** Puts a file (an image pasted into the chat) into a session; the result is its path there. */
  "files.upload": { params: UploadParams; result: Uploaded };
  /** Bakes the checkout's repo into a session image in a background job. */
  "image.bake": { params: BakeParams; result: Job };
  /** Opens the session: the protocol version both sides speak, and whether pier is set up. */
  "initialize": { params: InitializeParams; result: InitializeResult };
  /** A job's progress: every event so far, then each new one, ending with its done or failed event. */
  "job.watch": { params: JobRef; result: WatchResult<JobUpdate> };
  /** Stops a running job the way ctrl-c would, cleanup included. */
  "jobs.cancel": { params: JobRef; result: null };
  /** Background jobs this machine started, newest first (finished ones stay a day). */
  "jobs.list": { params: Empty; result: Job[] };
  /** The tail of a job's human log. */
  "jobs.log": { params: LogParams; result: LogText };
  /** The tail of a session's setup log (a failed create's own log for a create that never finished). */
  "logs.setup": { params: LogParams; result: LogText };
  /** The sidebar, Home and cockpit data, refreshed if older than a few seconds. */
  "overview.get": { params: Empty; result: Overview };
  /** The overview, pushed after every refresh. */
  "overview.watch": { params: Empty; result: WatchResult<Overview> };
  /** Destroys a repo's pooled sessions. */
  "pool.drain": { params: RepoRef; result: DrainResult };
  /** Tops up the checkout's repo pool now, in a background job. */
  "pool.fill": { params: PathParams; result: Job };
  /** Sets how many pooled sessions the checkout's repo keeps (0 turns the pool off and drains it). */
  "pool.setSize": { params: PoolSizeParams; result: null };
  /** What a create from the checkout containing path would carry: branch, HEAD, uncommitted changes, base. */
  "repos.inspect": { params: PathParams; result: CheckoutInfo };
  /** Links the repository containing path as a local checkout to act from. */
  "repos.link": { params: PathParams; result: Checkout };
  /** Forgets a linked checkout; the clone itself is untouched. */
  "repos.unlink": { params: PathParams; result: null };
  /** Starts a session from a linked checkout's HEAD (uncommitted edits travel too) in a background job. The row lists as starting until it is ready. */
  "sessions.create": { params: CreateParams; result: Job };
  /** Never parks this session when idle (it still stops on the runaway cap). */
  "sessions.keep": { params: SessionRef; result: null };
  /** The machine types a session can resize to: same CPU architecture, with shape and cost. */
  "sessions.machines": { params: SessionRef; result: Machine[] };
  /** Parks a running session now; its tmux layout is saved on the way down. */
  "sessions.park": { params: SessionRef; result: null };
  /** Destroys a session and its disk, or dismisses a failed create. */
  "sessions.remove": { params: SessionRef; result: null };
  /** Changes a session's machine type in a background job: one park and resume, disk intact. */
  "sessions.resize": { params: ResizeParams; result: Job };
  /** Wakes a parked session and waits until it answers. */
  "sessions.resume": { params: SessionRef; result: null };
  /** The settings page: groups, fields and current values for the active cloud. */
  "settings.get": { params: Empty; result: Settings };
  /** The machine catalog the settings picker offers, around a current type. */
  "settings.machines": { params: MachinesParams; result: Machine[] };
  /** Validates and saves one setting, returning the page as it now reads. */
  "settings.set": { params: SettingParams; result: Settings };
  /** Ends the server once every earlier request has answered and this reply is out. */
  "shutdown": { params: Empty; result: unknown };
  /** Hangs a terminal up. Its tmux windows keep running in the session. */
  "term.close": { params: TermRef; result: null };
  /** Opens a terminal tab into a session's tmux, on one of its windows. It counts as attached while open. */
  "term.open": { params: TermOpenParams; result: TermOpened };
  /** Opens a terminal on this machine for one of pier's interactive steps (a cloud login, setup). */
  "term.openLocal": { params: TermLocalParams; result: TermOpened };
  /** Closes a window and whatever runs in it. */
  "tmux.killWindow": { params: WindowParams; result: null };
  /** Adds a window in the session's checkout and returns it. */
  "tmux.newWindow": { params: NewWindowParams; result: Window };
  /** Renames a window. */
  "tmux.renameWindow": { params: RenameWindowParams; result: null };
  /** A session's tmux windows, in order. */
  "tmux.windows": { params: SessionRef; result: Window[] };
}

/** Every subscription topic: its watch params, its snapshot, and the data its events carry. */
export interface Watches {
  "chat": { params: SessionRef; snapshot: ChatSnapshot; data: ChatChange };
  "env": { params: SessionRef; snapshot: Env; data: Env };
  "job": { params: JobRef; snapshot: JobUpdate; data: JobUpdate };
  "overview": { params: Empty; snapshot: Overview; data: Overview };
}

export interface ServerNotifications {
  /** One progress event of a long request. */
  "$/progress": ProgressParams;
  /** Something about a session deserves the user's attention: its agent finished or needs them, its setup or create failed. Each id is sent once. */
  "notify": Notice;
  /** One update of a subscription. */
  "sub.event": SubEvent;
  /** A terminal's process ended. */
  "term.exit": TermExit;
  /** Terminal output, base64; acknowledge it with term.ack. */
  "term.output": TermData;
}

export interface ClientNotifications {
  /** Cancel an in-flight request. */
  "$/cancelRequest": CancelParams;
  /** Whether the client's window is focused, and what it shows. */
  "client.activity": ClientActivity;
  /** End a subscription. */
  "sub.cancel": SubCancelParams;
  /** How much terminal output the client has rendered. */
  "term.ack": TermAck;
  /** Keystrokes for a terminal, base64. */
  "term.input": TermData;
  /** Stop sending a hidden terminal's output. */
  "term.pause": TermRef;
  /** A terminal's new size. */
  "term.resize": TermSize;
  /** Send a terminal's output again. */
  "term.resume": TermRef;
}
